void dei_ask_ext_init(void)
{
    PINSEL4 |= 0x00400000;
    EXTMODE  = 0x02 ; 
    EXTPOLAR = 0x02 ;
	INTWAKE |= 2    ;
    EXTINT   = 0x02 ;    
}

